"""Machine-readable SCPI command catalog for IT-M3900D.

This catalog is generated from IT_M3900D_PyVISA_Class_AI_Task.md Appendix A/B.
The send header is produced at runtime by removing optional SCPI brackets and
using the long-form command path exactly enough for the instrument parser.
"""

from __future__ import annotations

import re
from collections.abc import Iterable

from .types import ScpiCommand, ScpiReturn


def _header_from_syntax(scpi: str) -> str:
    return scpi.split()[0].replace("[", "").replace("]", "")


def _method_key_from_header(header: str, *, query: bool) -> str:
    h = header.replace("?", "").strip(":")
    if h.startswith("*"):
        base = "star_" + h[1:]
    else:
        base = h
    base = re.sub(r"[^A-Za-z0-9]+", "_", base).strip("_").lower()
    return base + ("_query" if query else "")


def command_header(command: ScpiCommand) -> str:
    return _header_from_syntax(command.scpi)


def command_accepts_arguments(command: ScpiCommand) -> bool:
    return "<" in command.scpi or "[MIN" in command.scpi or "[MINimum" in command.scpi


