COMMANDS_BY_KEY: dict[str, ScpiCommand] = {cmd.key: cmd for cmd in COMMANDS}
COMMANDS_BY_SCPI: dict[str, ScpiCommand] = {cmd.scpi: cmd for cmd in COMMANDS}


def get_command(key: str) -> ScpiCommand:
    return COMMANDS_BY_KEY[key]


def find_commands(subsystem: str | None = None, *, operation: str | None = None, text: str | None = None) -> list[ScpiCommand]:
    result: Iterable[ScpiCommand] = COMMANDS
    if subsystem is not None:
        ss = subsystem.lower()
        result = [cmd for cmd in result if ss in cmd.subsystem.lower() or cmd.scpi.lower().startswith(ss)]
    if operation is not None:
        result = [cmd for cmd in result if cmd.operation == operation]
    if text is not None:
        t = text.lower()
        result = [cmd for cmd in result if t in cmd.key.lower() or t in cmd.scpi.lower()]
    return list(result)


def dangerous_commands() -> list[ScpiCommand]:
    return [cmd for cmd in COMMANDS if cmd.safety_class == "dangerous"]


def guarded_commands() -> list[ScpiCommand]:
    return [cmd for cmd in COMMANDS if cmd.safety_class in {"guarded", "dangerous"}]
